package com.fintechledger.risk;
import com.fintechledger.common.ApiException;import com.fintechledger.transfer.Transfer;import com.fintechledger.transfer.TransferRepository;import com.fintechledger.user.UserRepository;import java.math.BigDecimal;import java.time.Instant;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class RiskService{
 private final RiskAssessmentRepository risks;private final UserRepository users;private final TransferRepository transfers;private final BigDecimal threshold;
 public RiskService(RiskAssessmentRepository r,UserRepository u,TransferRepository transfers,@Value("${app.risk-transfer-threshold}") BigDecimal threshold){risks=r;users=u;this.transfers=transfers;this.threshold=threshold;}
 @Transactional public void assess(Transfer t){var rules=new ArrayList<String>();int score=0;if(t.getAmount().compareTo(threshold)>0){rules.add("LARGE_TRANSFER");score+=65;}if(transfers.countByInitiatedByEmailAndCreatedAtAfter(t.getInitiatedBy().getEmail(),Instant.now().minusSeconds(3600))>=5){rules.add("HIGH_FREQUENCY");score+=30;}if(rules.isEmpty())return;String level=score>=60?"HIGH":"MEDIUM";String explanation=rules.contains("LARGE_TRANSFER")?"Transfer exceeds the configured review threshold.":"Account initiated five or more transfers within the last hour.";risks.save(new RiskAssessment(t.getReference(),Math.min(score,100),level,rules,explanation));}
 @Transactional(readOnly=true)public List<RiskAssessment> list(){return risks.findAllByOrderByCreatedAtDesc();}
 @Transactional(readOnly=true)public RiskAssessment get(UUID id){return risks.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Risk assessment not found"));}
 @Transactional public RiskAssessment review(UUID id,String status,String email){if(!Set.of("APPROVED","ESCALATED","DISMISSED").contains(status))throw new ApiException(HttpStatus.BAD_REQUEST,"Review status is invalid");var risk=get(id);var user=users.findByEmail(email).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"User not found"));risk.review(status,user.getId());return risk;}
}
